(window.DETAIL_C = window.DETAIL_C || {})["mth-12-13"] = {"mth-12-13-m01":{"idea":"Order is the highest derivative present.","steps":["List the derivatives in the equation: third and second.","The highest is the third derivative.","So the order is 3. The power 2 on the second derivative does not change it."],"others":"2 is the order of the second derivative term only. 4 adds the orders by mistake. 1 is the order of y itself, which has no derivative.","trap":"Order ignores powers.","answer":"3"},"mth-12-13-m02":{"idea":"Degree is the power of the highest-order derivative.","steps":["The highest-order derivative is d²y/dx².","Its power is 3.","So the degree is 3. The powers 4 and 5 belong to lower terms."],"others":"2 is the order, not the degree. 4 and 5 are powers of other terms.","trap":"Degree uses the highest-order derivative only.","answer":"3"},"mth-12-13-m03":{"idea":"Remove the root first, then read off order and degree.","steps":["Square both sides: (d²y/dx²)² = 1 + (dy/dx)².","Now it is a polynomial in the derivatives.","The highest derivative has order 2, and its power is 2. So order 2, degree 2."],"others":"Degree 1 forgets to clear the root. Degree 1/2 is never allowed. Order 1 ignores the second derivative.","trap":"Clear roots before finding the degree.","answer":"2 and 2"},"mth-12-13-m04":{"idea":"Degree needs a polynomial in the derivatives.","steps":["The derivative dy/dx sits inside the sine.","So the equation is not a polynomial in dy/dx.","Degree is not defined. The order is 1."],"others":"0, 1 and 2 all assume a power can be read off, which it cannot here.","trap":"Sine of a derivative gives no degree.","answer":"not defined"},"mth-12-13-m05":{"idea":"Constants match the order.","steps":["Each integration step brings in one constant.","An equation of order 3 needs three integrations.","So the general solution has 3 independent constants."],"others":"1 and 2 are too few for three integrations. 4 is one too many.","trap":"Number of constants = order.","answer":"3"},"mth-12-13-m06":{"idea":"Two constants mean differentiate twice.","steps":["y = Ax + B, so dy/dx = A.","Differentiate again: d²y/dx² = 0.","Both constants are gone, and the order is 2."],"others":"dy/dx = A still has a constant. d²y/dx² = y has no link to this family. dy/dx = 0 is the family of horizontal lines only.","trap":"Remove every constant.","answer":"d²y/dx² = 0"},"mth-12-13-m07":{"idea":"Differentiate once and replace c·e^(2x) by y.","steps":["dy/dx = 2c·e^(2x).","Since c·e^(2x) = y, we get dy/dx = 2y.","One constant gives an equation of order 1."],"others":"dy/dx = y/2 divides instead of multiplying. dy/dx = e^(2x) still carries a missing constant. dy/dx = 2x is unrelated.","trap":"Substitute back y.","answer":"dy/dx = 2y"},"mth-12-13-m08":{"idea":"Differentiate the equation of the circle and drop r.","steps":["Differentiate x² + y² = r² with respect to x.","2x + 2y(dy/dx) = 0.","The constant r is gone. Divide by 2 to get x + y(dy/dx) = 0."],"others":"y + x(dy/dx) = 0 swaps the roles of x and y. x − y(dy/dx) = 0 has the wrong sign. x(dy/dx) = y describes lines through the origin.","trap":"Radius disappears after one differentiation.","answer":"x + y(dy/dx) = 0"},"mth-12-13-m09":{"idea":"Differentiate and replace m by y/x.","steps":["y = mx gives dy/dx = m.","From the original equation, m = y/x.","So dy/dx = y/x, or x(dy/dx) = y."],"others":"x(dy/dx) = −y has the wrong sign. dy/dx = m still has a constant. y(dy/dx) = x describes a different family.","trap":"Replace m by y/x.","answer":"x(dy/dx) = y"},"mth-12-13-m10":{"idea":"Two constants need two differentiations.","steps":["y′ = −a sin x + b cos x.","y″ = −a cos x − b sin x = −y.","So y″ + y = 0."],"others":"d²y/dx² = y has the wrong sign. The version with dy/dx added is not obtained from this family. dy/dx = −y is first order.","trap":"Second derivative is minus y.","answer":"d²y/dx² + y = 0"},"mth-12-13-m11":{"idea":"Differentiate twice and substitute.","steps":["y′ = cos x and y″ = −sin x.","y″ + y = −sin x + sin x = 0.","So it satisfies d²y/dx² + y = 0."],"others":"The version with dy/dx does not vanish for sin x. d²y/dx² − y = −2 sin x. dy/dx + y = cos x + sin x.","trap":"Verify by substituting.","answer":"d²y/dx² + y = 0"},"mth-12-13-m12":{"idea":"Integrate both sides.","steps":["dy/dx = 3x², so y = the integral of 3x² dx.","The integral is x³.","Add the constant: y = x³ + c."],"others":"6x is the derivative of 3x². x³/3 divides by 3 twice. 3x³ multiplies by 3 again.","trap":"Integral of 3x² is x³.","answer":"y = x³ + c"},"mth-12-13-m13":{"idea":"Separate the variables.","steps":["dy/y = dx.","Integrate: log|y| = x + k.","So y = c·eˣ, with c = ±eᵏ."],"others":"eˣ + c does not satisfy the equation. c·x and x + c are not solutions either.","trap":"The constant multiplies eˣ.","answer":"y = c·eˣ"},"mth-12-13-m14":{"idea":"Separate: y dy = x dx.","steps":["Multiply both sides by y and dx.","Integrate: y²/2 = x²/2 + k.","Multiply by 2: y² = x² + c."],"others":"y = x²/2 + c integrates the wrong sides. y = x + c has the wrong powers. y² = x + c has the wrong power on x.","trap":"Keep the squares.","answer":"y² = x² + c"},"mth-12-13-m15":{"idea":"Separate the variables.","steps":["dy/(1 + y²) = dx/(1 + x²).","Integrate both sides.","tan⁻¹ y = tan⁻¹ x + c."],"others":"log y = log x + c would be for dy/y = dx/x. y = x + c is not an integral of these. tan y = tan x + c applies the wrong function.","trap":"1 + y² gives tan⁻¹.","answer":"tan⁻¹ y = tan⁻¹ x + c"},"mth-12-13-m16":{"idea":"Write e^(x + y) as a product and separate.","steps":["e^(x + y) = eˣ·eʸ.","Separate: e^(−y) dy = eˣ dx.","Integrate: −e^(−y) = eˣ + k, so eˣ + e^(−y) = c."],"others":"eˣ + eʸ = c adds the wrong exponent. eˣ − e^(−y) = c has a wrong sign. e^(x + y) = c is not a solution.","trap":"Move eʸ to the left as e^(−y).","answer":"eˣ + e^(−y) = c"},"mth-12-13-m17":{"idea":"x dy + y dx is d(xy).","steps":["The left side is the exact differential of xy.","So d(xy) = 0.","Hence xy = c."],"others":"y = c·x would come from x dy = y dx. y/x = c is the same family as that. x + y = c has the wrong product.","trap":"Product rule in reverse.","answer":"xy = c"},"mth-12-13-m18":{"idea":"Find the general solution, then use the condition.","steps":["dy/dx = 2x gives y = x² + c.","Put x = 0 and y = 3: c = 3.","So y = x² + 3."],"others":"A constant left arbitrary is not a particular solution. y = x² − 3 uses the wrong sign for c. y = 2x² + 3 integrates 2x wrongly.","trap":"Use the condition to fix c.","answer":"y = x² + 3"},"mth-12-13-m19":{"idea":"Integrating factor is e to the integral of P.","steps":["P = 2/x.","The integral of 2/x is 2 log x.","I.F. = e^(2 log x) = x²."],"others":"1/x² has the exponent sign reversed. e^(x³/3) comes from the right side Q, not P. 2 log x forgets to take the exponential.","trap":"Use P, not Q.","answer":"x²"},"mth-12-13-m20":{"idea":"The integral of tan x is log|sec x|.","steps":["Here P = tan x.","The integral of tan x dx = log|sec x|.","I.F. = e^(log sec x) = sec x."],"others":"e^(tan x) integrates wrongly. tan x forgets the exponential step. cos x is the reciprocal.","trap":"e to the log gives the argument.","answer":"sec x"},"mth-12-13-m21":{"idea":"Use the integrating factor eˣ.","steps":["Here P = 1 and Q = 1, so I.F. = eˣ.","y·eˣ = the integral of eˣ dx = eˣ + c.","So y = 1 + c·e^(−x)."],"others":"y = 1 + c·eˣ does not satisfy the equation. y = c·e^(−x) solves the equation with Q = 0. y = 1 + c·x is not a solution.","trap":"Divide by eˣ at the end.","answer":"y = 1 + c·e^(−x)"},"mth-12-13-m22":{"idea":"Substitute y = vx.","steps":["With y = vx, dy/dx = v + x(dv/dx).","The right side is (x + vx)/x = 1 + v.","So v + x(dv/dx) = 1 + v, which gives x(dv/dx) = 1."],"others":"v(dv/dx) = x does not follow. dv/dx = 1 drops the factor x. x(dv/dx) = 1 + v forgets the v on the left side.","trap":"v cancels from both sides.","answer":"x(dv/dx) = 1"},"mth-12-13-m23":{"idea":"A ratio y/x on the right marks a homogeneous equation.","steps":["If dy/dx = f(y/x), the right side depends only on y/x.","Put y = vx and the equation becomes separable.","That type is called homogeneous."],"others":"Second order is about the highest derivative. Variable separable has x and y on different sides. Linear first order has the form dy/dx + Py = Q.","trap":"y/x means homogeneous.","answer":"a homogeneous equation"},"mth-12-13-m24":{"idea":"A decay rate is proportional to the amount and negative.","steps":["The rate dm/dt is proportional to m.","The amount falls, so the constant is negative.","dm/dt = −k·m, with k positive. The solution is m = m₀e^(−kt)."],"others":"dm/dt = k·m with k positive is growth. −k·t is proportional to time, not to m. −k is a constant rate.","trap":"Decay: minus sign.","answer":"dm/dt = −k·m, with k a positive constant"},"mth-12-13-m25":{"idea":"Slope is dy/dx.","steps":["The slope of the tangent is dy/dx.","It equals twice the x-coordinate.","So dy/dx = 2x. Integrating gives y = x² + c."],"others":"dy/dx = x/2 halves instead of doubling. dy/dx = 2y uses the wrong coordinate. y = 2x is not a differential equation.","trap":"Use x, not y.","answer":"dy/dx = 2x"},"mth-12-13-m26":{"idea":"Use the doubling condition in P = P₀e^(kt).","steps":["Doubling in 10 years: 2P₀ = P₀e^(10k).","So e^(10k) = 2 and 10k = log 2.","k = (log 2)/10, about 0.0693 per year."],"others":"(log 10)/2 swaps the numbers. 10 log 2 multiplies instead of dividing. 1/10 ignores the natural log.","trap":"Take the natural log of 2.","answer":"(log 2)/10"},"mth-12-13-n01":{"idea":"Integrate and use the point to find c.","steps":["y = x³ + c.","At (0, 2): c = 2.","y(2) = 8 + 2 = 10."],"trap":"Fix c before evaluating.","answer":"10"},"mth-12-13-n02":{"idea":"Solve by separation and use the condition.","steps":["y = c·eˣ.","y(0) = 1 gives c = 1.","y(1) = e = 2.718."],"trap":"e is about 2.718.","answer":"2.718"},"mth-12-13-n03":{"idea":"Separate: dy/y = 2x dx.","steps":["log y = x² + k, so y = c·e^(x²).","From y(0) = 2, c = 2.","y(1) = 2e = 5.437."],"trap":"Do not forget the 2.","answer":"5.437"},"mth-12-13-n04":{"idea":"Separate: y dy = x dx.","steps":["y² = x² + c.","From y(0) = 3, c = 9.","y(4)² = 16 + 9 = 25, so y = 5."],"trap":"Take the positive root.","answer":"5"},"mth-12-13-n05":{"idea":"Use the integrating factor eˣ.","steps":["y·eˣ = the integral of x·eˣ dx = (x − 1)eˣ + c, so y = x − 1 + c·e^(−x).","From y(0) = 1: −1 + c = 1, so c = 2.","y(1) = 0 + 2/e = 0.736."],"trap":"Divide by eˣ at the end.","answer":"0.736"},"mth-12-13-n06":{"idea":"The integrating factor is x².","steps":["y·x² = the integral of x⁴ dx = x⁵/5 + c.","From y(1) = 1: 1 = 1/5 + c, so c = 4/5.","At x = 2: 4y = 32/5 + 4/5 = 36/5, so y = 9/5 = 1.8."],"trap":"Multiply through by the factor.","answer":"1.8"},"mth-12-13-n07":{"idea":"Use the half-life.","steps":["m = m₀e^(−kt) with half-life 5 years.","15 years is three half-lives.","The fraction left is (1/2)³ = 0.125."],"trap":"Three half-lives, not 15.","answer":"0.125"},"mth-12-13-n08":{"idea":"Use N = 1000·e^(kt) and find k.","steps":["At t = 2: e^(2k) = 3, so k = (log 3)/2.","At t = 5: N = 1000·e^(5k) = 1000·3^(5/2).","3^(5/2) = 15.588, so N = 15588."],"trap":"3^(5/2) = 9√3.","answer":"15588"},"mth-12-13-n09":{"idea":"Put y = vx and separate the variables.","steps":["x(dv/dx) = 1, so v = log x + c.","y = x(log x + c). From y(1) = 0, c = 0.","y(e) = e × 1 = 2.718."],"trap":"log e = 1.","answer":"2.718"},"mth-12-13-n10":{"idea":"Solve dT/dt = −0.1·T by separation.","steps":["T = 80·e^(−0.1t).","At t = 10: T = 80·e^(−1).","e^(−1) = 0.36788, so T = 29.43."],"trap":"e^(−1) is about 0.368.","answer":"29.43"},"mth-12-13-n11":{"idea":"Separate: eʸ dy = eˣ dx.","steps":["eʸ = eˣ + c.","At x = 0: 2 = 1 + c, so c = 1.","Then eʸ = eˣ + 1, and y(1) = log(e + 1) = 1.313."],"trap":"e^(log 2) = 2.","answer":"1.313"}};
